  const s={view:'planning',dimension:'calendar',boardProject:'',projectQuery:'',statsScale:'month',statsDate:localDate(new Date()),statsProject:'',statsMetric:'involved',occurrence:'',query:'',data:{},project:'',month:localDate(new Date()).slice(0,7),detail:null,draft:null,draftActive:0,edit:null,followup:'',composer:'',busy:new Set(),detailEpoch:0,error:'',detailTimer:null,preview:null,knowledgeScope:'global',knowledgeQuery:'',knowledge:[],knowledgeScopes:[],detailTab:'overview',operationId:'',operationPayload:'',deliveryDirty:false,annotation:null,contextQuery:'',context:null,deliveryDraft:null,evidenceDraft:null,knowledgeCandidates:[],coordinationDrafts:{},active:true};
  const e=x=>escape(x==null?'':String(x)), i=x=>icon(x);
  const button=(name,label,attrs='')=>'<button type="button" data-planning-action="'+e(name)+'" '+attrs+'>'+label+'</button>';
  const safeMime=m=>/^image\/(?:png|jpe?g|gif|webp|avif)$/i.test(text(m));
  const shownDate=x=>{try{return x?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(x)):'';}catch(_){return text(x);}};
  function localDate(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
